  const [a, b] = await Promise.all([
    q("https://iss.moex.com/iss/engines.json?iss.meta=off"),
    q("https://iss.moex.com/iss/index.json?iss.meta=off"),
  ]);
  console.log("параллельно пришли оба ответа");
}
main();

